insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('86aab1bf-b120-5c1d-941b-866e7bc57d77', 'biology'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9BI0', 'Topic 1: Biological Molecules', 0) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('c179b9fa-bc45-556f-b9bc-58b563fb845c', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.1(i)', 'Know the difference between monosaccharides, disaccharides and polysaccharides.', 0, 0.7) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('208383d9-08bc-5851-93d5-81d0908a779a', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.1(ii)', 'Know the structure of the hexose glucose (alpha and beta) and the pentose ribose.', 1, 0.8) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('dc33e4a3-51e3-5180-98a8-edc652197821', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.1(iii)', 'Understand how monosaccharides (glucose, fructose, galactose) join to form disaccharides (sucrose, lactose and maltose) and polysaccharides (starch formed from amylose and amylopectin; glycogen) through condensation reactions forming glycosidic bonds, and how these can be split through hydrolysis reactions.', 2, 1.42) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('6fbd4dc5-2f7e-5545-91c0-3c6a50ffb52d', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.1(iv)', 'Understand how the structure of glucose, starch, glycogen and cellulose relates to their function.', 3, 0.99) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('7e241ac6-60db-559e-b010-5c9ba155e01f', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.2(i)', 'Understand how a triglyceride is synthesised, including the formation of ester bonds during condensation reactions between glycerol and three fatty acids.', 4, 1.11) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b125192d-74bf-5c2c-a4b7-3eaed2c35121', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.2(ii)', 'Know the differences between saturated and unsaturated lipids.', 5, 0.7) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ea377db4-2d0b-5534-b155-f2826ad1d7bb', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.2(iii)', 'Understand how the structure of lipids relates to their role in energy storage, waterproofing and insulation.', 6, 1.03) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e5e9b72a-d0eb-56bc-9752-a5ef11fb7228', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.2(iv)', 'Understand how the structure and properties of phospholipids relate to their function in cell membranes.', 7, 1.01) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('cabaa8bc-3966-532a-8ca7-1e55eefd71c4', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.3(i)', 'Know the structure of an amino acid (structures of specific amino acids are not required).', 8, 0.82) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('05e3e850-8d25-5ef2-877e-8cde136f06ea', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.3(ii)', 'Understand the formation of polypeptides and proteins (as amino acid monomers linked by peptide bonds in condensation reactions).', 9, 1.06) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('00c18e82-7df2-5907-9bd7-ec61833e294b', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.3(iii)', 'Understand the role of ionic, hydrogen and disulfide bonding in the structure of proteins.', 10, 0.99) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('a0ac9e61-0da5-53f4-a2ca-6b517a7217e7', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.3(iv)', 'Understand the significance of the primary, secondary, tertiary and quaternary structure of a protein in determining the properties of fibrous and globular proteins, including collagen and haemoglobin.', 11, 1.22) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('5dc34a3f-be7f-57d3-8dd9-483e6b1ed4e9', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.3(v)', 'Understand how the structure of collagen and haemoglobin are related to their function.', 12, 0.97) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('a4e07aee-e2e6-50aa-be8d-59e1c906e5bd', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.4(i)', 'Know the structure of DNA, including the structure of the nucleotides (purines and pyrimidines), base pairing, the two sugar-phosphate backbones, phosphodiester bonds and hydrogen bonds.', 13, 1.0) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('5abb67fa-c53b-5b44-b632-2933e0a5c49e', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.4(ii)', 'Understand how DNA is replicated semi-conservatively, including the role of DNA helicase, polymerase and ligase.', 14, 1.01) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('f3f26228-51a6-5233-8f9b-4e9ec399bd1d', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.4(iii)', 'Know that a gene is a sequence of bases on a DNA molecule coding for a sequence of amino acids in a polypeptide chain.', 15, 0.98) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('0769ae99-3c08-554d-b6cd-fc55f794a29a', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.4(iv)', 'Know the structure of mRNA including nucleotides, the sugar phosphate backbone and the role of hydrogen bonds.', 16, 0.86) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('63d50855-0303-5e92-a43e-2f784f0d7507', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.4(v)', 'Know the structure of tRNA, including nucleotides, the role of hydrogen bonds and the anticodon.', 17, 0.82) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('3f95d053-b477-5463-bc43-909250ec19a1', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.4(vi)', 'Understand the processes of transcription in the nucleus and translation at the ribosome, including the role of sense and anti-sense DNA, mRNA, tRNA and the ribosomes.', 18, 1.2) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ff10b8b7-b6d7-5226-883d-7b3ff0fab784', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.4(vii)', 'Understand the nature of the genetic code, including triplets coding for amino acids, start and stop codons, degenerate and non-overlapping nature, and that not all the genome codes for proteins.', 19, 1.27) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('8a03c787-0d8a-52dd-b68a-14841cf0dc9c', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.4(viii)', 'Understand the term gene mutation as illustrated by base deletions, insertions and substitutions.', 20, 0.97) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ba54d172-8b99-5a0f-b5d7-cd0a87b38f73', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.4(ix)', 'Understand the effect of point mutations on amino acid sequences, as illustrated by sickle cell anaemia in humans.', 21, 1.06) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ca84837a-4724-5701-b1f2-3799b8a0775a', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.5(i)', 'Know the structure of enzymes as globular proteins.', 22, 0.7) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('3fd5f8dd-cb01-585b-b19d-678c9ef2f2b0', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.5(ii)', 'Understand the concepts of specificity and the induced fit hypothesis.', 23, 0.92) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('2ff73e11-60a3-5476-9a6a-2fee8384657f', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.5(iii)', 'Understand that enzymes are catalysts that reduce activation energy.', 24, 0.9) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('2fb9fa45-21d6-59c9-aae1-5f6a7809a988', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.5(iv)', 'Understand how temperature, pH, substrate and enzyme concentration affect the rate of enzyme activity.', 25, 0.99) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('84a10960-8f39-5fe7-8aaf-1baf84859497', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.5(v)', 'Understand how the initial rate of enzyme activity can be measured and why this is important.', 26, 1.03) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('a76c8740-0088-5f1e-ab35-73c97971dd21', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.5(vi)', 'Understand how enzymes can be affected by competitive, non-competitive and end-product inhibition.', 27, 0.96) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('8a7da3a0-9194-5e19-bf58-3868944c7458', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.5(vii)', 'Know that enzymes catalyse a wide range of intracellular reactions as well as extracellular ones.', 28, 0.82) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('4723ceb8-ec47-5848-b3fa-bee651331b22', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.6(i)', 'Understand the role in plants of:', 29, 0.85) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('71edf052-960b-5f30-855a-a21f0b0b18a7', '86aab1bf-b120-5c1d-941b-866e7bc57d77', '1.7(i)', 'Understand the importance of the dipole nature of water leading to hydrogen bonding and the significance of the following to organisms:', 30, 1.11) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('b6b12e9f-c028-5431-842e-e8719e336100', 'biology'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9BI0', 'Topic 2: Cells, Viruses and Reproduction of Living Things', 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('983c61fe-2785-5852-a8c5-b9e2e49765f9', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.1(i)', 'Understand that cell theory is a unifying concept that states that cells are a fundamental unit of structure, function and organisation in all living organisms.', 0, 1.19) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('4304fa32-5793-5357-845a-27105189a860', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.1(ii)', 'Understand that in complex organisms, cells are organised into tissues, organs, and organ systems.', 1, 0.99) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('55f743a1-6953-5d5b-aa0a-84b5cfcd836c', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.1(iii)', 'Know the ultrastructure of prokaryotic cells and the structure of organelles, including: nucleoid, plasmids, 70S ribosomes and cell wall.', 2, 0.89) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('6a7189fb-5d3a-50ba-ab51-2db89cc8d0dd', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.1(iv)', 'Be able to distinguish between Gram positive and Gram negative bacterial cell walls and understand why each type reacts differently to some antibiotics.', 3, 1.15) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e2f15c3c-df82-5ec9-9196-fc77fa7644c2', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.1(v)', 'Know the ultrastructure of eukaryotic cells and the functions of organelles, including: nucleus, nucleolus, 80S ribosomes, rough and smooth endoplasmic reticulum, mitochondria, centrioles, lysosomes, Golgi apparatus, cell wall, chloroplasts, vacuole and tonoplast.', 4, 1.12) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('182ca3f4-b6be-505e-a67f-8571cc9c455b', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.1(vi)', 'Know how magnification and resolution can be achieved using light and electron microscopy.', 5, 0.79) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('8816eb89-32cb-5acb-b2f1-23a925c7a0d2', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.1(vii)', 'Understand the importance of staining specimens in microscopy.', 6, 0.88) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('08a65cf7-72cf-5649-9b0c-29ae726a4a65', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.2(i)', 'Understand that the classification of viruses is based on structure and nucleic acid types as illustrated by λ (lambda) phage (DNA), tobacco mosaic virus and Ebola (RNA) and human immunodeficiency virus (RNA retrovirus).', 7, 1.33) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b83c0f9b-409b-561b-bdd1-0f39166fd906', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.2(ii)', 'Know the lytic cycle of a virus and latency.', 8, 0.72) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('58084812-f24a-5564-8f00-286134657b8b', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.2(iii)', 'Know that viruses are not living cells and so antivirals must work by inhibiting virus replication.', 9, 0.84) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('99b26bb3-06b2-56fb-b950-b78b0a637db2', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.2(iv)', 'Know that as viruses can be difficult to treat once infection has occurred, the focus of disease control should be on preventing the spread, as exemplified by the 2014 Ebola outbreak in West Africa.', 10, 1.16) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('7d339e74-f7a0-5e11-ac3a-cf68f2d74555', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.2(v)', 'Be able to evaluate the ethical implications of using untested drugs during epidemics.', 11, 0.97) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('3e1ad0ef-67b2-5468-a597-8c27ea1854bf', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.3(i)', 'Know that the cell cycle is a regulated process in which cells divide into two identical daughter cells, and that this process consists of three main stages: interphase, mitosis and cytokinesis.', 12, 1.11) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('9a597f4e-8f25-5640-bbae-8a8acdf36fd3', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.3(ii)', 'Understand what happens to genetic material during the cell cycle, including the stages of mitosis.', 13, 1.01) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('784a9fda-fe50-515e-b7c1-80efaa8e9c8d', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.3(iii)', 'Understand how mitosis contributes to growth, repair and asexual reproduction.', 14, 0.92) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('869a957f-248d-517b-bb5c-6c9706b827ee', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.3(iv)', 'Understand how meiosis results in haploid gametes, including the stages of meiosis.', 15, 0.96) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('379a43f4-82e0-5629-8194-a56321908cd7', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.3(v)', 'Understand that meiosis results in genetic variation through recombination of alleles, including independent assortment and crossing over.', 16, 1.04) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('8055e816-4fc2-5719-be7f-b8469d957936', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.3(vi)', 'Understand what chromosome mutations are, as illustrated by translocations.', 17, 0.9) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('1847435f-9749-5591-b47e-ec40b9835124', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.3(vii)', 'Understand how non-disjunction can lead to polysomy, including Down''s syndrome, and monosomy, including Turner''s syndrome.', 18, 1.01) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('9687e261-ea63-5877-a818-43bf6bcc676a', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.4(i)', 'Understand the processes of oogenesis and spermatogenesis.', 19, 0.87) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('4c4fa481-bec0-5337-8bf0-d3f3f7dbed90', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.4(ii)', 'Understand the events of fertilisation from the first contact between the gametes to the fusion of nuclei.', 20, 1.04) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('18ca7020-ed99-53b3-8726-94f5adc0c6d7', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.4(iii)', 'Understand the early development of the embryo to blastocyst stage.', 21, 0.92) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('67d4e4f1-2656-5fd1-9d4d-603d8941cc26', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.5(i)', 'Understand how a pollen grain forms in the anther and the embryo sac forms in the ovule.', 22, 1.04) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('0bfb84ee-9e80-5440-864b-05677b839724', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.5(ii)', 'Understand how the male nuclei formed by division of the generative nucleus in the pollen grain reach the embryo sac, including the roles of the tube nucleus, pollen tube and enzymes.', 23, 1.29) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('7f97228e-e2ff-51c6-ac04-e4b7bff3ba8b', 'b6b12e9f-c028-5431-842e-e8719e336100', '2.5(iii)', 'Understand the process of double fertilisation inside the embryo sac to form a triploid endosperm and a zygote.', 24, 1.06) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('4c29d85a-4537-5c9e-a40c-cc798b7d7d90', 'biology'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9BI0', 'Topic 3: Classification and Biodiversity', 2) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d4c0ca01-505b-55e3-af28-5fa323308213', '4c29d85a-4537-5c9e-a40c-cc798b7d7d90', '3.1(i)', 'Know that the classification system consists of a hierarchy of domain, kingdom, phylum, class, order, family, genus and species.', 0, 0.89) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('7e3137bb-68bd-58f6-9656-387b79a64f61', '4c29d85a-4537-5c9e-a40c-cc798b7d7d90', '3.1(ii)', 'Understand the limitations of the definition of a species as a group of organisms with similar characteristics that interbreed to produce fertile offspring.', 1, 1.15) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('45a385b5-d9f7-5989-be79-b1ea0751e016', '4c29d85a-4537-5c9e-a40c-cc798b7d7d90', '3.1(iii)', 'Understand why it is often difficult to assign organisms to any one species or to identify new species.', 2, 1.06) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('9d1e99af-7349-5a48-851a-be1f383c1e80', '4c29d85a-4537-5c9e-a40c-cc798b7d7d90', '3.1(iv)', 'Understand how gel electrophoresis can be used to distinguish between species and determine evolutionary relationships.', 3, 1.01) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('cb37f69b-fdf9-534d-997c-9f9b3cf3d2be', '4c29d85a-4537-5c9e-a40c-cc798b7d7d90', '3.1(v)', 'Know that DNA sequencing and bioinformatics can be used to distinguish between species and determine evolutionary relationships.', 4, 0.86) on conflict (id) do nothing;
