insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('5da1b923-cabe-5b59-811d-0d3dadb4c9d1', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.4(iv)', 'Know that the peripheral nervous system is divided into autonomic and voluntary systems.', 12, 0.79) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('7cf235cd-6a58-54c1-bb2c-5a6028bab3b3', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.4(v)', 'Understand why the autonomic nervous system is divided into sympathetic and parasympathetic systems, which act antagonistically.', 13, 1.03) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('bf60d262-48f4-576f-a0e7-5f618ce4e53e', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.5(i)', 'Understand how the properties of the axon membrane and the transport of Na+ ions and K+ ions result in a resting potential.', 14, 1.13) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('864bf372-90d8-5a34-bc76-6118b53532aa', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.5(ii)', 'Understand how an action potential is formed and how it is propagated along an axon.', 15, 1.01) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b9cd176f-7c42-55eb-af72-6cff34e22f97', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.5(iii)', 'Understand why the speed of transmission along myelinated axons is greater than along non-myelinated axons, including the role of saltatory conduction.', 16, 1.11) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d0fdfaed-47c6-558d-ab93-32113c33bc2a', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.5(iv)', 'Understand the structure and function of a synapse, including the role of transmitter substances limited to acetylcholine and noradrenaline.', 17, 1.08) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('af7c8eb5-721c-5dbe-bc77-9e43b76863d6', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.5(v)', 'Understand the formation and effects of excitatory and inhibitory postsynaptic potentials.', 18, 0.94) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('c65ad515-9abe-5975-b5a4-4451182a5123', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.6(i)', 'Understand how the effects of drugs can be caused by their influence on synaptic transmission, including:', 19, 1.03) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('c6968296-fb20-5119-a309-1cbb8c420721', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.7(i)', 'Know the structure of the human retina.', 20, 0.68) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('7768e7ac-f8ce-5e28-ab3a-889c7b55178d', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.7(ii)', 'Understand the role of the rhodopsin in initiating action potentials.', 21, 0.92) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('7925c37d-eb0a-5e05-9fb4-bd7774b7bb41', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.7(iii)', 'Understand how the distribution of human rod and cone cells maintain vision in different light intensities.', 22, 1.03) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('64fc8424-c87e-512c-b544-e1f0e37d844d', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.8(i)', 'Understand how the autonomic nervous system controls heart rate including:', 23, 0.92) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d460b151-5a19-5cc7-adf4-91f0e6926832', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.8(ii)', 'Understand the role of the autonomic nervous system in causing the release of adrenaline to increase heart rate.', 24, 1.06) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('50270442-7cb3-5674-bb15-6df7cc6b424a', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.9(i)', 'Know the gross and microscopic structure of the mammalian kidney.', 25, 0.73) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('be74c653-d9c6-5498-8ada-e10eb83c1138', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.9(ii)', 'Understand how urea is produced in the liver from excess amino acids (details of the ornithine cycle are not required) and how it is removed from the bloodstream by ultrafiltration.', 26, 1.27) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('85f7fd79-97de-550e-9061-f465788950e2', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.9(iii)', 'Understand how solutes are selectively reabsorbed in the proximal tubule and how the Loop of Henle acts as a counter-current multiplier to increase the reabsorption of water.', 27, 1.22) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('bb08d287-2a55-5823-ab96-74dbdc9abff5', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.9(iv)', 'Understand how the pituitary gland and osmoreceptors in the hypothalamus, combined with the action of antidiuretic hormone (ADH) bring about negative feedback control of mammalian plasma concentration.', 28, 1.22) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('f6da03a8-e76f-5739-bcab-cf5a5cc75398', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.9(v)', 'Understand how the kidney of a kangaroo rat (Dipodomys sp.) is adapted for life in a dry environment.', 29, 1.06) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d96fda81-52cf-5c81-bc80-a8e316e02aba', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.9(vi)', 'Understand that an endotherm is able to produce heat through metabolic processes but an ectotherm must rely on the external environment.', 30, 1.11) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('60221232-0ab5-5860-8e94-7abc74850c48', '4b87721e-c4dd-5d82-81d6-302799c67593', '9.9(vii)', 'Understand how an endotherm is able to regulate its temperature through behaviour, and also physiologically through the autonomic nervous system, including the role of thermoreceptors, hypothalamus and the skin.', 31, 1.26) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('cff98cd3-658e-51e4-8014-e4c2d6257242', 'biology'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9BI0', 'Topic 10: Ecosystems', 9) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e12dc0d9-2192-5ab8-b462-652f100291f3', 'cff98cd3-658e-51e4-8014-e4c2d6257242', '10.1(i)', 'Understand what is meant by the term ecosystem and that they range in size.', 0, 0.99) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('9d40e164-733e-5996-8729-aac4b009ba46', 'cff98cd3-658e-51e4-8014-e4c2d6257242', '10.1(ii)', 'Understand what is meant by trophic levels.', 1, 0.87) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('9d3c0981-c701-5081-ac90-4d6c6c6b9b7f', 'cff98cd3-658e-51e4-8014-e4c2d6257242', '10.1(iii)', 'Understand the advantages and disadvantages of pyramids of numbers, biomass (dry) and energy as useful representations of ecosystem structure and how biomass and energy are transferred within them.', 2, 1.24) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ae67c7b5-29a0-59a9-85f2-91da5da36df7', 'cff98cd3-658e-51e4-8014-e4c2d6257242', '10.1(iv)', 'Know the ecological techniques used to assess abundance and distribution of organisms in a natural habitat, including types of quadrat, transects, ACFOR scales, percentage cover and individual counts.', 3, 1.05) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('546e74c5-131d-59e0-9a13-6f72cfcb4469', 'cff98cd3-658e-51e4-8014-e4c2d6257242', '10.1(v)', 'Be able to select appropriate ecological techniques according to the ecosystem and organisms to be studied.', 4, 1.03) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('439bc471-3e22-584e-ad97-dd5884a5cf53', 'cff98cd3-658e-51e4-8014-e4c2d6257242', '10.1(vi)', 'Be able to use statistical tests to analyse data, including t-test and Spearman rank correlation coefficient.', 5, 1.03) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('4a6c681c-649d-5756-8e18-b4621225996a', 'cff98cd3-658e-51e4-8014-e4c2d6257242', '10.2(i)', 'Understand how energy is transferred between trophic levels using the terms ''net primary productivity'' and ''gross primary productivity''.', 6, 1.06) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('bb957e7f-714b-5a20-b799-626cd3d1d16e', 'cff98cd3-658e-51e4-8014-e4c2d6257242', '10.2(ii)', 'Be able to calculate the efficiency of energy transfer between different trophic levels and account for the loss of energy at each level.', 7, 1.15) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('12016e94-b2f8-567a-920c-3cb933ad94e0', 'cff98cd3-658e-51e4-8014-e4c2d6257242', '10.2(iii)', 'Understand the significance of microorganisms in the recycling of nutrients within an ecosystem.', 8, 0.97) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('70b6ccbd-6623-5b4c-9605-000044f25456', 'cff98cd3-658e-51e4-8014-e4c2d6257242', '10.3(i)', 'Understand how ecosystems can develop over time, including use of the terms colonisation and succession and types of climax communities.', 9, 1.1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('baa55ac4-304a-5589-88a6-39734e85c526', 'cff98cd3-658e-51e4-8014-e4c2d6257242', '10.3(ii)', 'Understand the effects of biotic and abiotic factors on population size.', 10, 0.94) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d8754cbc-4487-52a1-a286-27398d8b90a4', 'cff98cd3-658e-51e4-8014-e4c2d6257242', '10.4(i)', 'Understand data relating to human influences on ecosystems, including climate change and depletion of biological resources, including overfishing.', 11, 1.06) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b6bb0dc6-df9e-5f49-9b23-a2a4f31202d3', 'cff98cd3-658e-51e4-8014-e4c2d6257242', '10.4(ii)', 'Understand the effect that treaties such as CITES have had on global biodiversity.', 12, 0.97) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('468c1d08-3d51-5e1f-b74b-285e1175bb06', 'cff98cd3-658e-51e4-8014-e4c2d6257242', '10.4(iii)', 'Understand the idea that sustainability of resources depends on effective management of the conflict between human needs and conservation, as illustrated by attempts to conserve fish stocks and reduce possible causes of climate change.', 13, 1.34) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('12581f56-055b-58f4-bfc2-f53961d2bff6', 'cff98cd3-658e-51e4-8014-e4c2d6257242', '10.4(iv)', 'Understand the role of the scientific journals, the peer review process and scientific conferences in validating evidence related to the debate about climate change.', 14, 1.17) on conflict (id) do nothing;
